export function StreamingResponse({
  text = "{{text}}",
  streaming = {{streaming}},
  accent = "{{accent}}",
  speed = "{{speed}}",
}) {
  const duration = { slow: "1.4s", normal: "1s", fast: "0.6s" }[speed] ?? "1s";
  return (
    <div role="status" aria-live="polite" style={{ maxWidth: 480, fontFamily: "system-ui, sans-serif",
      fontSize: 15, lineHeight: 1.6, color: "#241430", background: "#FAF7F2" }}>
      <p style={{ margin: 0 }}>
        {text}
        {streaming && (
          <span aria-hidden="true" className="sr-cursor" style={{ display: "inline-block", width: 2, height: "1em", marginLeft: 2,
            verticalAlign: "text-bottom", background: accent }} />
        )}
      </p>
      {streaming && (
        <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>
          Response is streaming
        </span>
      )}
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .sr-cursor { animation: sr-react-blink ${duration} step-end infinite; }
          @keyframes sr-react-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
        }
      `}</style>
    </div>
  );
}
